"""SQLite-backed storage for the household ledger."""

import sqlite3
from pathlib import Path

SCHEMA = """
CREATE TABLE IF NOT EXISTS transactions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    date TEXT NOT NULL,
    description TEXT NOT NULL,
    category TEXT NOT NULL,
    amount REAL NOT NULL
);
"""


def connect(db_path: str | Path = ":memory:") -> sqlite3.Connection:
    """Open a connection and ensure the schema exists."""
    conn = sqlite3.connect(db_path)
    conn.execute(SCHEMA)
    conn.commit()
    return conn


class Ledger:
    """Thin wrapper around a database connection."""

    def __init__(self, conn: sqlite3.Connection) -> None:
        self.conn = conn

    def add_transaction(self, date: str, description: str, category: str, amount: float) -> int:
        """Insert a transaction and return its new id."""
        cur = self.conn.execute(
            "INSERT INTO transactions (date, description, category, amount) VALUES (?, ?, ?, ?)",
            (date, description, category, amount),
        )
        self.conn.commit()
        return cur.lastrowid

    def transactions(self, category: str | None = None) -> list[dict]:
        """Return all transactions, optionally filtered by category."""
        if category is None:
            rows = self.conn.execute(
                "SELECT id, date, description, category, amount FROM transactions ORDER BY date, id"
            ).fetchall()
        else:
            rows = self.conn.execute(
                "SELECT id, date, description, category, amount "
                "FROM transactions WHERE category = ? ORDER BY date, id",
                (category,),
            ).fetchall()
        return [
            {"id": r[0], "date": r[1], "description": r[2], "category": r[3], "amount": r[4]}
            for r in rows
        ]

    def total(self, category: str | None = None) -> float:
        """Sum of amounts, optionally for a single category."""
        if category is None:
            row = self.conn.execute("SELECT COALESCE(SUM(amount), 0) FROM transactions").fetchone()
        else:
            row = self.conn.execute(
                "SELECT COALESCE(SUM(amount), 0) FROM transactions WHERE category = ?",
                (category,),
            ).fetchone()
        return row[0]

    def close(self) -> None:
        self.conn.close()


def open_ledger(db_path: str | Path = ":memory:") -> Ledger:
    """Open a database file (or :memory:) and return a Ledger."""
    return Ledger(connect(db_path))

