"""Guard test: the project must use only the Python standard library."""

import ast
import os
import sys
import unittest

PROJECT_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
LOCAL_PACKAGES = {"ledger", "tests"}
EXEMPT = {"__future__"}  # not in sys.stdlib_module_names but pure stdlib


def top_level_modules(path: str) -> set[str]:
    with open(path, encoding="utf-8") as f:
        tree = ast.parse(f.read(), filename=path)
    mods = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            mods.update(alias.name.split(".")[0] for alias in node.names)
        elif isinstance(node, ast.ImportFrom):
            # "from .db import ..." has node.module None; "from ledger import ..." has a module
            if node.level == 0 and node.module:
                mods.add(node.module.split(".")[0])
    return mods


class StdlibOnlyTests(unittest.TestCase):
    def test_no_pip_packages(self) -> None:
        offenders = []
        for dirpath, _dirnames, filenames in os.walk(PROJECT_ROOT):
            if ".git" in dirpath.split(os.sep):
                continue
            for name in filenames:
                if not name.endswith(".py"):
                    continue
                path = os.path.join(dirpath, name)
                for mod in top_level_modules(path):
                    if mod in EXEMPT or mod in LOCAL_PACKAGES:
                        continue
                    if mod not in sys.stdlib_module_names:
                        offenders.append(f"{os.path.relpath(path, PROJECT_ROOT)}: {mod}")
        self.assertEqual(offenders, [], "non-stdlib imports found:\n" + "\n".join(offenders))


if __name__ == "__main__":
    unittest.main()

